// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;

import java.lang.reflect.Method;
import java.util.Arrays;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

import com.fasterxml.jackson.databind.ObjectMapper;

/** No finite operation count, however large, is the representation of an absent ceiling. */
class LmdbNativeUnknownUpperBoundContractTest {

	@Test
	void onlyTheUpperAxisMayExplicitlyBeInfinite() {
		LmdbNativeCostVector vector = assertDoesNotThrow(() -> LmdbNativeCostVector.bounds(
				Feature.SCANNED_ROW, 2D, 3D, Double.POSITIVE_INFINITY));
		assertUnknown(vector, 2D, 3D);
		assertThatThrownBy(() -> LmdbNativeCostVector.bounds(Feature.SCANNED_ROW,
				Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY))
						.isInstanceOf(IllegalArgumentException.class);
		assertThatThrownBy(() -> LmdbNativeCostVector.bounds(Feature.SCANNED_ROW,
				0D, Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY)).isInstanceOf(IllegalArgumentException.class);
		for (double high : new double[] { Double.NaN, Double.NEGATIVE_INFINITY, -1D }) {
			assertThatThrownBy(() -> LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 0D, 0D, high))
					.isInstanceOf(IllegalArgumentException.class);
		}
	}

	@Test
	void unknownWorkRetainsItsFiniteLargeFloor() {
		assertUnknown(LmdbNativeCostQuote.ofWork(LmdbNativeWork.atLeast(2e15D), 1D).total(), 2e15D, 2e15D);
	}

	@Test
	void finiteLargeCeilingsScaleNormallyInsteadOfStickingToALegacySentinel() {
		LmdbNativeCostVector scaled = LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 0D, 2D, 2e15D).scale(0.1D);
		assertThat(scaled.high(Feature.SCANNED_ROW)).isEqualTo(2e14D);
		assertThat(unitPrior().price(scaled).known()).isTrue();
	}

	@Test
	void unknownSurvivesCopiesHullsAdditionAndPositiveScaling() {
		LmdbNativeCostVector unknown = unknown();
		LmdbNativeCostVector copied = LmdbNativeCostVector.builder().add(unknown).build();
		LmdbNativeCostVector hull = LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 3D, 3D,
				Math.max(unknown.high(Feature.SCANNED_ROW), 2e15D));
		assertUnknown(copied, 3D, 3D);
		assertUnknown(hull, 3D, 3D);
		assertUnknown(unknown.plus(LmdbNativeCostVector.point(Feature.SCANNED_ROW, 1D)), 4D, 4D);
		assertUnknown(unknown.scale(0.1D), 3D * 0.1D, 3D * 0.1D);
	}

	@Test
	void zeroAnnihilatesUnknownWhilePositiveFractionalRepetitionDoesNot() {
		assertThat(unknown().scale(0D)).isEqualTo(LmdbNativeCostVector.zero());
		assertThat(LmdbNativeCostVectors.repeated(unknown(), 0D, LmdbNativeWork.RowBounds.ZERO).isZero()).isTrue();
		assertThat(LmdbNativeCostVectors
				.repeated(LmdbNativeCostVector.zero(), 0D, new LmdbNativeWork.RowBounds(0D, Double.POSITIVE_INFINITY))
				.isZero()).isTrue();
		LmdbNativeCostVector repeated = LmdbNativeCostVectors.repeated(
				LmdbNativeCostVector.point(Feature.SCANNED_ROW, 0.1D), 1D,
				new LmdbNativeWork.RowBounds(0D, Double.POSITIVE_INFINITY));
		assertUnknown(repeated, 0D, 0.1D);
	}

	@Test
	void exactFiniteMaximumRemainsFiniteButArithmeticOverflowDoesNot() {
		LmdbNativeCostVector maximum = LmdbNativeCostVector.point(Feature.SCANNED_ROW, Double.MAX_VALUE);
		assertThat(maximum.high(Feature.SCANNED_ROW)).isFinite().isEqualTo(Double.MAX_VALUE);
		assertThat(unitPrior().price(maximum).known()).isTrue();
		assertUnknown(maximum.plus(maximum), Double.MAX_VALUE, Double.MAX_VALUE);
		assertUnknown(maximum.scale(2D), Double.MAX_VALUE, Double.MAX_VALUE);
		assertUnknown(LmdbNativeCostVector.builder().add(maximum).add(maximum).build(),
				Double.MAX_VALUE, Double.MAX_VALUE);
	}

	@Test
	void finiteProofProductOverflowIsUnknownRatherThanACertifiedMaximum() {
		LmdbNativeWork.RowBounds product = LmdbNativeCostVectors.productBounds(
				new LmdbNativeWork.RowBounds(0D, Double.MAX_VALUE / 2D),
				new LmdbNativeWork.RowBounds(4D, 4D));
		assertThat(product.high()).isPositive().isInfinite();
		assertThat(product.low()).isZero();
	}

	@Test
	void upperDotOverflowIsUnknownButExpectedDotStillSaturates() {
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(Feature.SCANNED_ROW, Double.MAX_VALUE);
		double[] coefficients = new double[Feature.values().length];
		coefficients[Feature.SCANNED_ROW.ordinal()] = 2D;
		assertThat(vector.dotHigh(coefficients)).isPositive().isInfinite();
		assertThat(vector.dotExpected(coefficients)).isEqualTo(Double.MAX_VALUE);
		assertThat(new LmdbNativeStaticPrior(coefficients).price(vector).known()).isFalse();
	}

	@Test
	void zeroCoefficientsDoNotMakeTrueUnknownWorkEligibleAsPriced() {
		LmdbNativeStaticPrior zeroPrior = new LmdbNativeStaticPrior(new double[Feature.values().length]);
		assertThat(unknown().dotHigh(new double[Feature.values().length])).isZero();
		assertThat(zeroPrior.price(unknown()).known()).isFalse();
		assertThat(zeroPrior.price(LmdbNativeCostVector.point(Feature.SCANNED_ROW, 2e15D)).known()).isTrue();
	}

	@Test
	void consumptionAndIndependentBufferPhasesKeepUnknownCeilings() {
		LmdbNativeCostVector consumed = LmdbNativeCostVector.consumed(LmdbNativeCostVector.zero(), unknown(), 0.25D);
		assertUnknown(consumed, 0D, 0.75D);
		LmdbNativeCostQuote.ChunkedWork chunks = new LmdbNativeCostQuote.ChunkedWork(
				LmdbNativeCostVector.point(Feature.INTERPRETED_ROW, 8D), 8D, 2)
						.withIndependentPhase(new LmdbNativeCostQuote.ChunkedWork(unknown(), 8D, 2))
						.withBufferedConsumer(8D, 2);
		LmdbNativeCostQuote quote = new LmdbNativeCostQuote(LmdbNativeCostVector.zero(),
				LmdbNativeCostVector.zero(), 8D, false, false, chunks);
		assertThat(quote.forSlice(1D).high(Feature.SCANNED_ROW)).isPositive().isInfinite();
		assertThat(quote.forSlice(0D).isZero()).isTrue();
		assertThat(quote.bounded()).isFalse();
	}

	@Test
	void subtractingTwoUnknownFeatureCeilingsCannotEraseTheRemainder() throws Exception {
		Method subtract = LmdbNativeOfferBridge.class.getDeclaredMethod("subtract",
				LmdbNativeCostVector.class, LmdbNativeCostVector.class);
		subtract.setAccessible(true);
		assertUnknown((LmdbNativeCostVector) subtract.invoke(null, unknown(), unknown()), 0D, 0D);
	}

	@Test
	void featureCorrectionCannotTurnUnknownIntoFinite() throws Exception {
		double[] ratios = new double[Feature.values().length];
		Arrays.fill(ratios, 0.5D);
		Method correction = LmdbNativeAdaptiveCostModel.class.getDeclaredMethod("applyFeatureCorrection",
				LmdbNativeCostVector.class, LmdbNativeStoreCostModel.Correction.class);
		correction.setAccessible(true);
		assertUnknown((LmdbNativeCostVector) correction.invoke(null, unknown(),
				new LmdbNativeStoreCostModel.Correction(ratios, true)), 1.5D, 1.5D);
	}

	@Test
	void jsonEncodesUnknownHighAsNullWhileKeepingFiniteCountsNumeric() throws Exception {
		Method serialize = NativeAggregateCostQuotes.class.getDeclaredMethod("vector", StringBuilder.class,
				LmdbNativeCostVector.class);
		serialize.setAccessible(true);
		StringBuilder output = new StringBuilder();
		serialize.invoke(null, output, unknown().plus(LmdbNativeCostVector.point(Feature.DECODED_ROW, 2e15D)));
		assertThat(output.toString()).doesNotContain("Infinity", "NaN");
		var tree = new ObjectMapper().readTree(output.toString());
		assertThat(tree.path("SCANNED_ROW").path("high").isNull()).isTrue();
		assertThat(tree.path("SCANNED_ROW").path("low").doubleValue()).isEqualTo(3D);
		assertThat(tree.path("SCANNED_ROW").path("expected").doubleValue()).isEqualTo(3D);
		assertThat(tree.path("DECODED_ROW").path("high").doubleValue()).isEqualTo(2e15D);
	}

	private static LmdbNativeCostVector unknown() {
		return LmdbNativeCostQuote.ofWork(LmdbNativeWork.atLeast(3D), Double.NaN).total();
	}

	private static LmdbNativeStaticPrior unitPrior() {
		double[] coefficients = new double[Feature.values().length];
		coefficients[Feature.SCANNED_ROW.ordinal()] = 1D;
		return new LmdbNativeStaticPrior(coefficients);
	}

	private static void assertUnknown(LmdbNativeCostVector vector, double low, double expected) {
		assertThat(vector.low(Feature.SCANNED_ROW)).isEqualTo(low);
		assertThat(vector.expected(Feature.SCANNED_ROW)).isEqualTo(expected);
		assertThat(vector.high(Feature.SCANNED_ROW)).isPositive().isInfinite();
	}
}
